import ast,base64,hashlib,json
s=base64.b64decode('').decode('utf-8')
assert hashlib.sha256(s.encode()).hexdigest()=='9ce815ccfa8a9c8c5158c1cf76d55966f07c2c095537bc91726e0cebfe1aa0a8'
t=ast.parse(s,filename='rog_launcher.py')
compile(t,'rog_launcher.py','exec')
print(json.dumps({'file':'rog_launcher.py','bytes':len(s.encode()),'sha256':hashlib.sha256(s.encode()).hexdigest(),'ast_and_compile_only':True,'module_executed':False,'host_calls':0,'syntax':'passed'},sort_keys=True))
